<?php/***********************************************************InboundController.phpProduct :Version : 1.0Release : 1Date Created : Aug 11, 2019Developed By  : Mohamad Mantach   PHP Department itm SolutionsAll Rights Reserved ,   itm Solutions COPYRIGHT 2019Page Description :***********************************************************/namespace App\Http\Controllers\CallCenter;use App;use App\Http\Controllers\Controller;use App\models\Accounting\TransactionMovements;use App\models\Accounting\Transactions;use App\models\Inventory\WareHouseMovement;use App\models\PayRolls\PayrollsComissions;use Validator;use Input;use Illuminate\Http\Request;use Illuminate\Http\Response;use Session;use Redirect;use Auth;use Config;use DB;use Illuminate\Support\Facades\Hash;use App\models\CostCenter\Categories;use App\models\CostCenter\CostCenters;use App\models\CostCenter\CostCenterTypes;use App\models\CostCenter\CostCenterStatus;use App\models\Users\Users;use App\models\Users\UserTypes;use App\models\CallCenter\InboundCall;use App\models\CallCenter\MaintenanceTypes;use App\models\CRM\CRMAccounts;use App\models\Inventory\Customers;use App\models\Inventory\Products;use App\models\Billing\PaymentTypes;use App\models\System\Currency;use App\models\CallCenter\CallResults;use App\models\CallCenter\CallResultsWorkflow;use App\models\Inventory\WareHouses;use App\models\Inventory\Stocks;use App\models\Accounting\ChartAccounts;use App\models\CallCenter\InboundCallProducts;use App\models\System\Areas;use App\models\System\Regions;class InboundController extends Controller{    /**     * Page to control Inbound Calls Management     *     * @author Moe mantach     * @access public     * @return unknown     */    public function index()    {        $default_company_id = session('default_company_id');        $lst_telemarketings = Users::whereUIsActive(1)->whereFkCompanyId($default_company_id)->whereUIsDeleted(0)->whereUUserType(UserTypes::USER_TYPE_TELEMARKETING)->get();        $lst_maint_types = MaintenanceTypes::whereMtIsDeleted(0)->get();        $lst_payment_types = PaymentTypes::wherePtIsDeleted(0)->get();        $lst_currencies = Currency::all();        $lst_results = CallResults::whereCrIsDeleted(0)->get();        $lst_products = Products::wherePProductIsDeleted(0)->get();        $lst_technicians = Users::whereUIsActive(1)->whereFkCompanyId($default_company_id)->whereUIsDeleted(0)->whereUUserType(UserTypes::USER_TYPE_TECHNICIAN)->get();        $lst_admins = Users::whereUIsActive(1)->whereFkCompanyId($default_company_id)->whereUIsDeleted(0)->whereUUserType(UserTypes::USER_TYPE_ADMIN)->get();        $lst_areas = Areas::all();        $lst_regions = Regions::all();        $data = array(            "lst_telemarketings" => $lst_telemarketings,            "lst_technicians" => $lst_technicians,            "lst_payment_types" => $lst_payment_types,            "lst_products" => $lst_products,            "lst_currencies" => $lst_currencies,            "lst_admins" => $lst_admins,            "lst_results" => $lst_results,            "lst_areas" => $lst_areas,            "lst_regions" => $lst_regions,            "lst_maint_types" => $lst_maint_types        );        return Response()->view('callcenter.inboundcalls',$data);    }    /**     * Display list of Inbound call saved in the database     *     * @author Moe Mantach     * @param Request $request     * @return View     */    public function DisplayList(Request $request)    {        $page_number            = $request->input('page_number');        $general_search         = $request->input('general_search');        $ic_technician_id           = $request->input('ic_technician_id');        $ic_result_id           = $request->input('ic_result_id');        $ic_maintenance_type           = $request->input('ic_maintenance_type');        $ic_call_date           = $request->input('ic_call_date');        $ic_archived_call           = $request->input('ic_archived_call');        $cl_area                = $request->input('cl_area');        $cl_region              = $request->input('cl_region');        $default_company_id = session('default_company_id');        $nbr_rows_per_pages     = Config::get('appconfig.max_rows_per_page');        if($page_number > 1)            $skip = ( $page_number - 1 ) * $nbr_rows_per_pages ;        else            $skip = 0;        $inboundcall_cond = InboundCall::whereIcIsDeleted(0)->whereIcClosedVoucher(0)->whereIcCompanyId($default_company_id);        if(strlen($general_search) > 0)        {            // Group all search conditions within a single 'where' clause using a closure            $inboundcall_cond = $inboundcall_cond->where(function ($query) use ($general_search) {                $query->where('ic_call_outcome', 'LIKE', '%' . $general_search . '%')                    ->orWhere('ic_notes', 'LIKE', '%' . $general_search . '%')                    ->orWhere('ic_resolution_notes', 'LIKE', '%' . $general_search . '%')                    ->orWhere('ic_client_code', 'LIKE', '%' . $general_search . '%')                    ->orWhere('ic_contract_code', 'LIKE', '%' . $general_search . '%');            });        }        if($ic_technician_id > 0 )        {            $inboundcall_cond = $inboundcall_cond->where('ic_technician_id','=',$ic_technician_id);        }        if($cl_area > 0)        {            $inboundcall_cond = $inboundcall_cond->whereHas('Client', function($query)  use ($cl_area) {                $query->where('ca_billing_area', $cl_area);            });        }        if($cl_region > 0)        {            $inboundcall_cond = $inboundcall_cond->whereHas('Client', function($query)  use ($cl_region) {                $query->where('ca_billing_region', $cl_region);            });        }        if($ic_maintenance_type > 0 )        {            $inboundcall_cond = $inboundcall_cond->where('ic_maintenance_type','=',$ic_maintenance_type);        }        if(strlen($ic_call_date) > 0 )        {            $inboundcall_cond = $inboundcall_cond->where('ic_call_date','<=',$ic_call_date);        }        if(strlen($ic_archived_call) > 0 )        {            $inboundcall_cond = $inboundcall_cond->where('ic_issue_resolved','=',$ic_archived_call);        }        if($ic_result_id > 0 )        {            $inboundcall_cond = $inboundcall_cond->where('ic_result_id','=',$ic_result_id);        }        $inboundcall_count = $inboundcall_cond->count();        $total_pages = ceil( $inboundcall_count /$nbr_rows_per_pages );        $total_pages = intval($total_pages);        $lst_inboundcall_info = $inboundcall_cond->skip($skip)->take($nbr_rows_per_pages)->orderBy('ic_id', 'asc')->get();        $data = array(            "lst_inboundcall_info" => $lst_inboundcall_info        );        $result_array = array();        $result_array['total_pages'] = $total_pages;        $result_array['display'] = view("callcenter.listinbound",$data)->render();        return Response()->json($result_array);    }    /**     * get client information of current call     *     * @author Moe Mantach     * @param Request $request     * @return void     */    public function GetClientInfo(Request $request)    {        $ic_id = $request->input('ic_id');        $inboundcall_info = InboundCall::find($ic_id);        $result_array = array();        $result_array['client_name'] = $inboundcall_info->Client->ca_account_name;        $result_array['client_mobile'] = $inboundcall_info->Client->ca_account_mobile;        $result_array['client_code'] = $inboundcall_info->Client->ca_account_code;        $result_array['is_error'] = 0;        $result_array['error_msg'] = "Operation Successful";        return Response()->json($result_array);    }    /**     * get list of current call result and display it inside pop     * @param type $request     */    public function GetListCallResul(Request $request)    {        $ic_id = $request->input('ic_id');        $result_array = array();        $lst_result_workflow = CallResultsWorkflow::whereCwIsDeleted(0)->whereCwCallId($ic_id)->orderBy('cw_creation_date','DESC')->get();        $data = array(            "lst_result_workflow" => $lst_result_workflow        );        $result_array['is_error'] = 0;        $result_array['display'] = view('callcenter.listcallresults',$data)->render();        return Response()->json($result_array);    }    /**     * get info of call result workflow     * @param Request $request     * @return \Illuminate\Http\JsonResponse     */    public function GetResultWorkflowinfo(Request $request)    {        $cw_id = $request->input('cw_id');        $result_array = array();        $res_workflow = CallResultsWorkflow::find($cw_id);        $result_array['is_error'] = 0;        $result_array['cw_id'] = $res_workflow->cw_id;        $result_array['cw_result_id'] = $res_workflow->cw_result_id;        $result_array['cw_result_note'] = $res_workflow->cw_result_note;        $result_array['cw_assigned_to'] = $res_workflow->cw_assigned_to;        $result_array['cw_creation_date'] = $res_workflow->cw_creation_date;        return Response()->json($result_array);    }    public function SaveCallResultInfo(Request $request)    {        $ic_call_id           = $request->input('ic_call_ids');        $cw_id           = $request->input('cw_id');        $cw_result_id           = $request->input('cw_result_id');        $cw_creation_date           = $request->input('cw_creation_date');        $cw_callback_date           = $request->input('cw_callback_date');        $cw_assigned_to           = $request->input('cw_assigned_to');        $cw_result_note           = $request->input('cw_result_note');        $result_array = array();        if($cw_id == 0)            $result_info = new CallResultsWorkflow();        else            $result_info = CallResultsWorkflow::find($cw_id);        $result_info->cw_call_id = $ic_call_id;        $result_info->cw_result_id = $cw_result_id;        $result_info->cw_creation_date = $cw_creation_date;        $result_info->cw_assigned_to = $cw_assigned_to;        $result_info->cw_result_note = $cw_result_note;        if($cw_result_id == 1)            $result_info->cw_callback_date = $cw_callback_date;        $result_info->save();        $call_info = InboundCall::find($ic_call_id);        $call_info->ic_result_id = $cw_result_id;        $call_info->ic_result_notes = $cw_result_note;        $call_info->ic_technician_id = $cw_assigned_to;        $call_info->ic_callback_date = $cw_creation_date;        $call_info->save();        $result_array['is_error'] = 0;        return Response()->json($result_array);    }    public function GenerateAndDownloadList(Request $request)    {       $general_search         = $request->input('general_search');        $ic_technician_id           = $request->input('ic_technician_id');        $ic_maintenance_type           = $request->input('ic_maintenance_type');        $ic_call_date           = $request->input('ic_call_date');        $ic_archived_call           = $request->input('ic_archived_call');        $ic_result_id           = $request->input('ic_result_id');        $cl_area           = $request->input('cl_area');        $cl_region           = $request->input('cl_region');        $inboundcall_cond = InboundCall::whereIcIsDeleted(0)->whereIcClosedVoucher(0);        if(strlen($general_search) > 0)        {            // Group all search conditions within a single 'where' clause using a closure            $inboundcall_cond = $inboundcall_cond->where(function ($query) use ($general_search) {                $query->where('ic_call_outcome', 'LIKE', '%' . $general_search . '%')                    ->orWhere('ic_notes', 'LIKE', '%' . $general_search . '%')                    ->orWhere('ic_resolution_notes', 'LIKE', '%' . $general_search . '%')                    ->orWhere('ic_client_code', 'LIKE', '%' . $general_search . '%')                    ->orWhere('ic_contract_code', 'LIKE', '%' . $general_search . '%');            });        }        if($ic_technician_id > 0 )        {             $inboundcall_cond = $inboundcall_cond->where('ic_technician_id','=',$ic_technician_id);        }        if($ic_maintenance_type > 0 )        {             $inboundcall_cond = $inboundcall_cond->where('ic_maintenance_type','=',$ic_maintenance_type);        }        if(strlen($ic_call_date) > 0 )        {             $inboundcall_cond = $inboundcall_cond->where('ic_call_date','<=',$ic_call_date);        }        if(strlen($ic_archived_call) > 0 )        {             $inboundcall_cond = $inboundcall_cond->where('ic_issue_resolved','=',$ic_archived_call);        }        if($ic_result_id > 0 )        {             $inboundcall_cond = $inboundcall_cond->where('ic_result_id','=',$ic_result_id);        }        if($cl_area > 0)        {            $inboundcall_cond = $inboundcall_cond->whereHas('Client', function($query)  use ($cl_area) {                $query->where('ca_billing_area', $cl_area);            });        }        if($cl_region > 0)        {            $inboundcall_cond = $inboundcall_cond->whereHas('Client', function($query)  use ($cl_region) {                $query->where('ca_billing_region', $cl_region);            });        }        $lst_inboundcall_info = $inboundcall_cond->orderBy('ic_id', 'asc')->get();        $calls_array = array();        $i = 0;        foreach ($lst_inboundcall_info as $index => $call_info) {            if($call_info->Technician != null && $call_info->Client != null)            {                $ic_maintenance_type = $call_info->ic_maintenance_type;                $calls_array[$call_info->Technician->id]['user_info']['id'] = $call_info->Technician->id;                $calls_array[$call_info->Technician->id]['user_info']['name'] = $call_info->Technician->u_fullname;                $calls_array[$call_info->Technician->id]['call_info'][$i]['ca_account_name'] = $call_info->Client->ca_account_name;                $calls_array[$call_info->Technician->id]['call_info'][$i]['ca_account_code'] = $call_info->Client->ca_account_code;                $calls_array[$call_info->Technician->id]['call_info'][$i]['ca_account_mobile'] = $call_info->Client->ca_account_mobile;                $calls_array[$call_info->Technician->id]['call_info'][$i]['ca_billing_address'] = $call_info->Client->ca_billing_address;                $calls_array[$call_info->Technician->id]['call_info'][$i]['ic_id'] = $call_info->ic_id;                $calls_array[$call_info->Technician->id]['call_info'][$i]['ic_maintenance_type'] = $call_info->MaintenanceType ? $call_info->MaintenanceType->mt_type : "N/A";                $calls_array[$call_info->Technician->id]['call_info'][$i]['ic_call_index'] = $call_info->ic_call_index;                $calls_array[$call_info->Technician->id]['call_info'][$i]['ic_call_subject'] = $call_info->ic_call_subject;                $calls_array[$call_info->Technician->id]['call_info'][$i]['ic_call_date'] = $call_info->ic_call_date;                $calls_array[$call_info->Technician->id]['call_info'][$i]['ic_call_start_time'] = $call_info->ic_call_start_time;                $calls_array[$call_info->Technician->id]['call_info'][$i]['ic_call_outcome'] = $call_info->ic_call_outcome;                $calls_array[$call_info->Technician->id]['call_info'][$i]['ic_notes'] = $call_info->ic_notes;                $calls_array[$call_info->Technician->id]['call_info'][$i]['ic_resolution_notes'] = $call_info->ic_resolution_notes;                $calls_array[$call_info->Technician->id]['call_info'][$i]['ic_result_notes'] = $call_info->ic_result_notes;                $calls_array[$call_info->Technician->id]['call_info'][$i]['ic_product_machine_id'] = $call_info->ic_product_machine_id;                $calls_array[$call_info->Technician->id]['call_info'][$i]['cr_result_title'] = $call_info->CallResult ? $call_info->CallResult->cr_result_title : "-";                $calls_array[$call_info->Technician->id]['call_info'][$i]['ic_resolution_date'] = $call_info->ic_resolution_date;                $calls_array[$call_info->Technician->id]['call_info'][$i]['ic_callback_date'] = $call_info->ic_callback_date;                $i++;            }        }        $data = array(            "lst_inboundcall_info" => $lst_inboundcall_info,            "calls_array" => $calls_array,        );        $contract_document = view('templates.lstcalls',$data)->render();       $pdf = App::make('snappy.pdf.wrapper');        $pdf->setOption('encoding', 'UTF-8');        $pdf->setOption('margin-top', 10);        $pdf->setOption('margin-bottom', 10);        $pdf->setOption('margin-left', 10);        $pdf->setOption('margin-right', 10);        $pdf->setOption('orientation', 'Landscape'); // Set orientation to landscape        $pdf->loadHTML($contract_document);        return $pdf->inline();    }    /**     * Add stock to current inboundcall voucher     * @param Request $request     * @return void     */    public function AddProductStock(Request $request)    {        $p_id = $request->input('p_id');        $cp_quantity        = $request->input('cp_quantity');        $products_stock     = $request->input('products_stock');        $ic_tech_id         = $request->input('ic_tech_id');        $technician_info = Users::find($ic_tech_id);        $fk_warehouse_id = $technician_info->fk_warehouse_id;        $stock_array = array();        $product_info = Products::find($p_id);        $result_array = array();        $warehouse_info = WareHouses::whereWLinkedTo($ic_tech_id)->get();        if(count($warehouse_info) == 0){            $result_array['is_error'] = 1;            $result_array['error_msg'] = 'No Warehouse Linked to technician Account';            return Response()->json($result_array);        }        $stock_count = Stocks::whereIsIsDeleted(0)->whereFkWarehouseId($warehouse_info[0]->w_id)->where('fk_product_id', $p_id)->count();        if($stock_count == 0)        {            $result_array['is_error'] = 1;            $result_array['error_msg'] = 'Stock Does Not Exist in the warehouse of technician';            return Response()->json($result_array);        }        if($products_stock != "")            $stock_array = json_decode($products_stock);        array_push($stock_array,array(            'p_id' => $p_id,            'cp_quantity' => $cp_quantity,            'product_name' => $product_info->p_product_name,        ));        $data = array(            "product_info" => $product_info,            "cp_quantity" => $cp_quantity        );        $result_array['is_error'] = 0;        $result_array['display'] = view('callcenter.voucherstockrecord',$data)->render();        $result_array['products_stock'] = $stock_array;        return Response()->json($result_array);    }    /**     * Function of Adding a new Cost Center category     *     * @author Moe Mantach     * @access public     * @return \Illuminate\View\View|\Illuminate\Contracts\View\Factory     */    public function AddForm()    {        $lst_clients = CRMAccounts::whereCaIsDeleted(0)->get();        $lst_sales = Users::whereUIsActive(1)->whereUIsDeleted(0)->whereUUserType(UserTypes::USER_TYPE_SALES)->get();        $lst_products = Products::wherePProductIsDeleted(0)->get();        $lst_maint_types = MaintenanceTypes::whereMtIsDeleted(0)->get();        $lst_technicians = Users::whereUIsActive(1)->whereUIsDeleted(0)->whereUUserType(UserTypes::USER_TYPE_TECHNICIAN)->get();        $lst_results = CallResults::whereCrIsDeleted(0)->get();        $lst_admins = Users::whereUIsActive(1)->whereUIsDeleted(0)->whereUUserType(UserTypes::USER_TYPE_ADMIN)->get();        $count_calls = InboundCall::whereIcIsDeleted(0)->count() + 1;        $ic_call_index = str_pad($count_calls, 7, '0', STR_PAD_LEFT);        $data = array(            "lst_clients" => $lst_clients,            "lst_products" => $lst_products,            "lst_maint_types" => $lst_maint_types,            "lst_technicians" => $lst_technicians,            "lst_sales" => $lst_sales,            "lst_admins" => $lst_admins,            "lst_results" => $lst_results,            "ic_call_index" => $ic_call_index,        );        return view('callcenter.addinboundcall',$data);    }    public function GetNewMaintenanceNumber(Request $request)    {        $count_calls = InboundCall::whereIcIsDeleted(0)->count() + 1;        $result_array = array();        $result_array['is_error'] = 0;        $result_array['maintenance_number'] = $count_calls;        return Response()->json($result_array);    }    /**     * Save Maintenance Voucher Information     *     * @author Moe Mantach     * @access public     * @param Request $request     */    public function SaveMaintenanceVoucherInfo(Request $request)    {        $result_array = array();        $ic_ids = $request->input('ic_ids');        $ic_resolution_date = $request->input('ic_resolution_date');        $ic_doc_number = $request->input('ic_doc_number');        $ic_call_index = $request->input('ic_call_index');        $ic_comission = $request->input('ic_comission');        $ic_payment_type = $request->input('ic_payment_type');        $ic_visit_price = $request->input('ic_visit_price');        $ic_currency_id = $request->input('ic_currency_id');        $products_stock = $request->input('products_stock');        $ic_tech_id = $request->input('ic_tech_id');        $ic_is_paid = $request->has('ic_is_paid') ? 1 : 0;        $default_company_id = session('default_company_id');        $products_stock_array = json_decode($products_stock);        $voucher_info = InboundCall::find($ic_ids);        $voucher_info->ic_resolution_date = $ic_resolution_date;        $voucher_info->ic_doc_number = $ic_doc_number;        $voucher_info->ic_call_index = $ic_call_index;        $voucher_info->ic_comission = $ic_comission;        $voucher_info->ic_payment_type = $ic_payment_type;        $voucher_info->ic_visit_price = $ic_visit_price;        $voucher_info->ic_currency_id = $ic_currency_id;        if($ic_is_paid == 1)            $voucher_info->ic_closed_voucher = 1;        $voucher_info->ic_issue_resolved = 1;        $voucher_info->save();        // get client info        $client_info = CRMAccounts::whereCaAccountCode($voucher_info->ic_client_code)->first();        $ca_id = $client_info->ca_id;        // save stock for calls and remove quantity from stock        //w_linked_to        $ic_technician_id = $voucher_info->ic_technician_id;        // add comission for technician for voucher        if( $ic_comission > 0 && $voucher_info->ic_comission_paid == 0 )        {            $payroll_comissions = new PayrollsComissions();            $payroll_comissions->pc_employee_id = $ic_tech_id;            $payroll_comissions->pc_company_id = session('company_id');            $payroll_comissions->pc_comission_value = $ic_comission;            $payroll_comissions->pc_currency_id = $ic_currency_id;            $payroll_comissions->pc_effective_date = date('Y-m-d');            $payroll_comissions->pc_comission_label = "Commission on file # "  . $client_info->ca_account_code . " - " . $client_info->ca_account_name . " For Maintenance voucher " . $ic_doc_number;            $payroll_comissions->pc_deal_id = 0;            $payroll_comissions->save();            $voucher_info = InboundCall::find($ic_ids);            $voucher_info->ic_comission_paid = 1;            $voucher_info->save();        }        $warehouse_info = WareHouses::whereWIsDeleted(0)->whereWLinkedTo($ic_tech_id)->get();        if(count($warehouse_info) == 0)        {            $result_array['is_error'] = 1;            $result_array['error_msg'] = "Warehouse not found";            return Response()->json($result_array);        }        $warehouse_info = $warehouse_info[0];        $warehouse_id = $warehouse_info->w_id;        $parts_total_cost = 0;        if( $products_stock_array != null )        {            foreach ($products_stock_array as $index => $stock)            {                $stock_info = Stocks::whereFkWarehouseId($warehouse_id)->whereFkProductId($stock->p_id)->where('is_quanity','>=',$stock->cp_quantity)->first();                $product_info = Products::find($stock->p_id);                $warehouse_info = WareHouses::find($warehouse_id);                if($stock_info == null)                {                    $result_array['is_error'] = 1;                    $result_array['error_msg'] = "Stock not found";                    return Response()->json($result_array);                }                $sdata = $stock_info;                $stock_obj = Stocks::find($sdata->is_id);                $stock_obj->is_quanity = $sdata->is_quanity - $stock->cp_quantity;                $stock_obj->save();                $cp_total_cost = $sdata->is_price_item * $stock->cp_quantity;                $price_item = $sdata->is_price_item;                $warehouse_movement = new WareHouseMovement();                $warehouse_movement->wm_warehouse_id = $warehouse_id;                $warehouse_movement->wm_product_id = $stock->p_id;                $warehouse_movement->wm_quantity = $stock->cp_quantity;                $warehouse_movement->wm_action_date = date('Y-m-d');                $warehouse_movement->wm_action_type = "MAINTENANCE_VOUCHER";                $warehouse_movement->wm_action_description = "Get " .$stock->cp_quantity . " of " . $product_info->mp_product_name . " From " . $warehouse_info->w_warehouse_name . " In Maintenance Voucher #" .  $ic_doc_number;                $warehouse_movement->save();                //save callcenter client product                $call_product = new InboundCallProducts();                $call_product->cp_client_id = $ca_id;                $call_product->fk_call_id = $ic_ids;                $call_product->cp_warehouse_id = $warehouse_id;                $call_product->cp_product_id = $stock->p_id;                $call_product->cp_technician_id = $ic_technician_id;                $call_product->cp_quantity = $stock->cp_quantity;                $call_product->cp_total_cost = $cp_total_cost;                $call_product->cp_total_price = $cp_total_cost;                $call_product->cp_total_price_item = $price_item;                $call_product->save();                // save accounting Record for Every Product                $parts_total_cost = $parts_total_cost + $stock_info->is_price_item;            }        }        $transaction_id = $voucher_info->ic_transaction_id;        // save accounting records        $delete = Transactions::whereAtId($transaction_id)->delete();        $delete = TransactionMovements::whereFkTranId($transaction_id)->delete();        $transaction = new Transactions();        $todays_date = date('Y-m-d');        $transaction->at_transaction_date   = $todays_date;        $transaction->at_creation_date      = $todays_date;        $transaction->at_accounting_doc     = "Transaction For Products on MV Call #" . $ic_doc_number;        $transaction->fk_acc_journal_id     = 1;        $transaction->at_currency_id        = $ic_currency_id;        $transaction->save();        $at_id = $transaction->at_id;        {            $trans_mov= new TransactionMovements();            $trans_mov->tm_company_id            = $default_company_id;            $trans_mov->fk_tran_id              = $at_id;            $trans_mov->tm_ledger_account       = 713;            $trans_mov->tm_sub_ledger_account   = 713 ;            $trans_mov->tm_debit                = 0;            $trans_mov->tm_credit               = $ic_visit_price;            $trans_mov->tm_creation_date        = date('Y-m-d');            $trans_mov->tm_transaction_date        = date('Y-m-d');            $trans_mov->tm_currency_id          = $ic_currency_id;            $trans_mov->tm_ledger_label         = "Debit Products For MV Call  #" . $ic_doc_number;            $trans_mov->save();            $trans_mov= new TransactionMovements();            $trans_mov->tm_company_id            = $default_company_id;            $trans_mov->fk_tran_id              = $at_id;            $trans_mov->tm_ledger_account       = $client_info->ca_maintenance_account;            $trans_mov->tm_sub_ledger_account   = $client_info->ca_maintenance_account ;            $trans_mov->tm_debit                = $ic_visit_price;            $trans_mov->tm_credit               = 0;            $trans_mov->tm_creation_date        = date('Y-m-d');            $trans_mov->tm_transaction_date        = date('Y-m-d');            $trans_mov->tm_currency_id          = $ic_currency_id;            $trans_mov->tm_ledger_label         = "Debit Products For MV Call  #" . $ic_doc_number;            $trans_mov->save();        }        if($ic_is_paid == 1)        {            $trans_mov= new TransactionMovements();            $trans_mov->tm_company_id            = $default_company_id;            $trans_mov->fk_tran_id              = $at_id;            $trans_mov->tm_ledger_account       = $client_info->ca_maintenance_account;            $trans_mov->tm_sub_ledger_account   = $client_info->ca_maintenance_account ;            $trans_mov->tm_debit                = 0;            $trans_mov->tm_credit               = $ic_visit_price;            $trans_mov->tm_creation_date        = date('Y-m-d');            $trans_mov->tm_transaction_date        = date('Y-m-d');            $trans_mov->tm_currency_id          = $ic_currency_id;            $trans_mov->tm_ledger_label         = "Credit Products For MV Call  #" . $ic_doc_number;            $trans_mov->save();            $type_info = PaymentTypes::find($ic_payment_type);            $pt_payment_account = $type_info->pt_payment_account;            $trans_mov= new TransactionMovements();            $trans_mov->fk_tran_id              = $at_id;            $trans_mov->tm_company_id            = $default_company_id;            $trans_mov->tm_ledger_account       = $pt_payment_account;            $trans_mov->tm_sub_ledger_account   = $pt_payment_account;            $trans_mov->tm_debit                = 0;            $trans_mov->tm_credit               = $ic_visit_price;            $trans_mov->tm_creation_date        = date('Y-m-d');            $trans_mov->tm_transaction_date        = date('Y-m-d');            $trans_mov->tm_currency_id          = $ic_currency_id;            $trans_mov->tm_ledger_label         = "Credit Visit Price For MV Call  #" . $ic_doc_number;            $trans_mov->save();        }        // add new maintenance call on save        if($voucher_info->ic_maintenance_type == MaintenanceTypes::MAINTENANCE_RO || $voucher_info->ic_maintenance_type == MaintenanceTypes::MAINTENANCE_SCHEDULED_MAIN)        {           $today = date('Y-m-d');           $call_date = "";           if($voucher_info->ic_maintenance_type == MaintenanceTypes::MAINTENANCE_RO)               $call_date = date('Y-m-d', strtotime('+18 month', strtotime($today)));           else               $call_date = date('Y-m-d', strtotime('+3 month', strtotime($today)));           $count_calls = InboundCall::whereIcIsDeleted(0)->count();           $index = $count_calls + 1;           $call_index = "CC" . sprintf('%05d', $index);           $call_info = new InboundCall();           $call_info->ic_call_index           = $call_index;           $call_info->ic_sales_id             = $voucher_info->fk_sales_id;           $call_info->ic_telemarketing_id     = $voucher_info->fk_telemarketing_id;           $call_info->ic_client_code          = $voucher_info->ic_client_code;           $call_info->ic_contract_code        = $voucher_info->ic_contract_code;           $call_info->ic_serial_number        = $voucher_info->ic_serial_number;           $call_info->ic_call_date            = $call_date;           $call_info->ic_call_start_time      = "08:00";           $call_info->ic_maintenance_type     = $voucher_info->ic_maintenance_type;           $call_info->save();        }        $result_array['is_error'] = 0;        $result_array['error_msg'] = "Operation Completed Successfully";        return Response()->json($result_array);    }    /**     * Save Cost Center Category Info to the database     *     * @author Moe Mantach     * @access public     * @param Request $request     *     * @return Response Json     */    public function SaveInboundCallInfo(Request $request)    {        $ic_id                          = $request->input('ic_id');        $fk_customer_id             = $request->input('fk_customer_id');        $ic_sales_id             = $request->input('ic_sales_id');        $ic_client_code             = $request->input('ic_client_code');        $ic_contract_code             = $request->input('ic_contract_code');        $ic_call_date             = $request->input('ic_call_date');        $ic_call_start_time             = $request->input('ic_call_start_time');        $ic_call_duration             = $request->input('ic_call_duration');        $ic_call_outcome             = $request->input('ic_call_outcome');        $ic_issue_resolved             = $request->input('ic_issue_resolved');        $ic_call_subject             = $request->input('ic_call_subject');        $ic_customer_product             = $request->input('ic_customer_product');        $ic_product_machine_id             = $request->input('ic_product_machine_id');        $ic_under_warranty             = $request->has('ic_under_warranty') ? 1 : 0;        $ic_warranty_expiry             = $request->input('ic_warranty_expiry');        $ic_notes                   = $request->input('ic_notes');        $ic_item_problem                  = $request->input('ic_item_problem');        $ic_bill_situation                  = $request->input('ic_bill_situation');        $ic_technician_id                  = $request->input('ic_technician_id');        $ic_result_id                  = $request->input('ic_result_id');        $ic_maintenance_type                  = $request->input('ic_maintenance_type');        $default_company_id = session('default_company_id');        $result_array = array();        $inboundcall_info = new InboundCall();        if( $ic_id != null )        {            $inboundcall_info = InboundCall::find($ic_id);            $inboundcall_info->ic_last_updated_by = session('user_id');            $inboundcall_info->ic_last_updated_date = date('Y-m-d');        }        else        {            $inboundcall_info->ic_created_by = session('user_id');            $inboundcall_info->ic_created_at = date('Y-m-d');        }        $count_calls = InboundCall::whereIcIsDeleted(0)->count();        $index = $count_calls + 1;        $call_index = "CC" . sprintf('%05d', $index);        $inboundcall_info->ic_call_index               = $call_index;        $inboundcall_info->fk_customer_id               = $fk_customer_id;        $inboundcall_info->ic_company_id               = $default_company_id;        $inboundcall_info->ic_sales_id               = $ic_sales_id;        $inboundcall_info->ic_client_code               = $ic_client_code;        $inboundcall_info->ic_contract_code               = $ic_contract_code;        $inboundcall_info->ic_call_date               = $ic_call_date;        $inboundcall_info->ic_call_start_time               = $ic_call_start_time;        $inboundcall_info->ic_call_duration               = $ic_call_duration;        $inboundcall_info->ic_call_outcome               = $ic_call_outcome;        $inboundcall_info->ic_issue_resolved               = $ic_issue_resolved;        $inboundcall_info->ic_notes               = $ic_notes;        $inboundcall_info->ic_call_subject               = $ic_call_subject;        $inboundcall_info->ic_customer_product               = $ic_customer_product;        $inboundcall_info->ic_product_machine_id               = $ic_product_machine_id;        $inboundcall_info->ic_under_warranty               = $ic_under_warranty;        $inboundcall_info->ic_warranty_expiry               = $ic_warranty_expiry;        $inboundcall_info->ic_item_problem               = $ic_item_problem;        $inboundcall_info->ic_bill_situation               = $ic_bill_situation;        $inboundcall_info->ic_technician_id               = $ic_technician_id;        $inboundcall_info->ic_result_id                     = $ic_result_id;        $inboundcall_info->ic_maintenance_type                     = $ic_maintenance_type;        $inboundcall_info->save();        $result_array['is_error']  = 0;        $result_array['error_msg'] = 'Inbound Call Information Has been saved';        return Response()->json($result_array);    }    /**     * Display Edit Cost Center category Form Page     *     * @author Moe Mantach     * @access public     * @param unknown $tc_id     */    public function EditForm( $ic_id )    {        $inboundcall_info          = InboundCall::find($ic_id);        $lst_clients = CRMAccounts::whereCaIsDeleted(0)->get();        $lst_sales = Users::whereUIsActive(1)->whereUIsDeleted(0)->whereUUserType(UserTypes::USER_TYPE_SALES)->get();        $lst_technicians = Users::whereUIsActive(1)->whereUIsDeleted(0)->whereUUserType(UserTypes::USER_TYPE_TECHNICIAN)->get();        $lst_products = Products::wherePProductIsDeleted(0)->get();        $lst_maint_types = MaintenanceTypes::whereMtIsDeleted(0)->get();        $lst_results = CallResults::whereCrIsDeleted(0)->get();        $lst_admins = Users::whereUIsActive(1)->whereUIsDeleted(0)->whereUUserType(UserTypes::USER_TYPE_ADMIN)->get();        $data = array(            "inboundcall_info" => $inboundcall_info,            "lst_sales" => $lst_sales,            "lst_clients" => $lst_clients,            "lst_admins" => $lst_admins,            "lst_results" => $lst_results,            "lst_technicians" => $lst_technicians,            "lst_products" => $lst_products,            "inboundcall_info" => $inboundcall_info,            "lst_maint_types" => $lst_maint_types,        );        return view('callcenter.editinboundcall',$data);    }    /**     * Delete Cost Center information     *     * @author Moe Mantach     * @access public     * @param Request $request     * @return unknown     */    public function DeleteInboundCallInformation(Request $request)    {        $result_array = array();        $ic_id= $request->input('ic_id');        $inboundcall_info = InboundCall::find( $ic_id );        $inboundcall_info->ic_is_deleted          = 1;        $inboundcall_info->ic_deleted_by          = Session('user_id');        $inboundcall_info->save();        $result_array['is_error']   = 0;        $result_array['error_msg']  = "Operation Complete Successfully";        return Response()->json($result_array);    }}